CREATE OR REPLACE FUNCTION public.get_client_commit_v1(p_commit_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  SELECT CASE WHEN c.commit_id IS NULL THEN jsonb_build_object('code',404)
    WHEN NOT public.can_read_client_commit(c.commit_id) THEN jsonb_build_object('code',403)
    ELSE jsonb_build_object('code',200,'data',jsonb_build_object(
      'commitId',c.commit_id,'occurredAt',c.occurred_at,
      'actorDisplay',c.actor_display,'actorKind',c.actor_kind,
      'source',c.source,'changeClass',c.change_class,'reason',c.reason,
      'items',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'entityType',i.entity_type,'entityId',i.entity_id,
        'operation',i.operation,'safeLabel',i.safe_label,
        'changedFields',i.changed_fields) ORDER BY i.item_index),'[]')
        FROM public.client_commit_items i WHERE i.commit_id=c.commit_id),
      'components',(SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'component',cc.component,'scopeType',cc.scope_type,
        'scopeId',cc.scope_id,'revision',cc.resulting_revision,
        'publishedRevision',p.published_revision,
        'publicationStatus',CASE
          WHEN p.published_revision>=cc.resulting_revision
            THEN 'published' ELSE 'pending' END)
        ORDER BY cc.component),'[]')
        FROM public.client_commit_components cc
        LEFT JOIN LATERAL (
          SELECT max(cp.published_revision) published_revision
          FROM public.client_sync_publications cp
          WHERE cp.component=cc.component
            AND cp.scope_type=cc.scope_type
            AND cp.scope_id=cc.scope_id
        ) p ON true
        WHERE cc.commit_id=c.commit_id))) END
  FROM (SELECT * FROM public.client_commits WHERE commit_id=p_commit_id) c
  RIGHT JOIN (SELECT 1) seed ON true;
$function$
;
REVOKE ALL ON FUNCTION public.get_client_commit_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION public.get_client_commit_v1(uuid) TO postgres,authenticated,service_role;


-- Source: database/functions/events/get_event_feedback_export_for_edit.sql
CREATE OR REPLACE FUNCTION public.get_event_feedback_export_page_internal_v1(
    p_occasion bigint
,p_after bigint DEFAULT NULL,p_limit integer DEFAULT NULL)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $function$
DECLARE
    v_items JSONB;
BEGIN
    IF NOT public.can_read_schedule_feedback(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 403,
            'message', 'Insufficient permissions'
        );
    END IF;

    IF NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN
        RETURN jsonb_build_object(
            'code', 404,
            'message', 'Feedback feature is not enabled for this occasion'
        );
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'event_id', e.id,
                'event_title', e.title,
                'event_start_time', e.start_time,
                'event_end_time', e.end_time,
                'feedback_id', f.id,
                'created_at', f.created_at,
                'updated_at', f.updated_at,
                'rating', f.rating,
                'note', f.note,
                'user_name', NULLIF(
                    btrim(CONCAT_WS(' ', ui.name, ui.surname)), ''
                ),
                'is_anonymous', f."user" IS NULL
            )
            ORDER BY e.start_time ASC, e.title ASC, f.updated_at DESC
        ),
        '[]'::jsonb
    )
    INTO v_items
    FROM (SELECT * FROM public.event_feedback WHERE occasion=p_occasion AND (p_after IS NULL OR id>p_after) ORDER BY id LIMIT p_limit) f
    JOIN public.events e ON e.id = f.event
    LEFT JOIN public.user_info ui ON ui.id = f."user"
    WHERE f.occasion = p_occasion;

    RETURN jsonb_build_object('code', 200, 'data', v_items);
END;
$function$;

REVOKE ALL ON FUNCTION public.get_event_feedback_export_page_internal_v1(bigint,bigint,integer) FROM PUBLIC,anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.get_event_feedback_export_for_edit(p_occasion bigint)
RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path=public,extensions AS $$
 SELECT public.get_event_feedback_export_page_internal_v1(p_occasion,NULL,NULL);
$$;
REVOKE ALL ON FUNCTION public.get_event_feedback_export_for_edit(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_event_feedback_export_for_edit(bigint) TO authenticated;


-- Source: database/functions/authoring/history.sql
CREATE OR REPLACE FUNCTION public.get_authoring_history(p_occasion bigint,p_organization bigint,p_unit bigint,p_action text,p_payload jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE result jsonb; lim int:=coalesce((p_payload->>'limit')::int,50); commit_row public.client_commits%ROWTYPE;
 order_id bigint:=(p_payload->>'orderId')::bigint; include_unit boolean:=coalesce((p_payload->>'includeUnit')::boolean,false);
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF lim NOT BETWEEN 1 AND 100 OR (include_unit AND (p_unit IS NULL OR NOT public.can_read_unit_client_commits(p_unit))) THEN
  RAISE insufficient_privilege USING MESSAGE='invalid history scope'; END IF;
 IF order_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM eshop.orders WHERE id=order_id AND occasion=p_occasion) THEN
  RAISE insufficient_privilege USING MESSAGE='order outside history scope'; END IF;
 IF p_action='commits' THEN
  RETURN public.get_client_commits_scoped_internal_v1(p_occasion,(p_payload#>>'{before,occurredAt}')::timestamptz,(p_payload#>>'{before,commitId}')::uuid,lim,'{}',include_unit,false);
 ELSIF p_action='commit' THEN
  SELECT * INTO commit_row FROM public.client_commits WHERE commit_id=(p_payload->>'commitId')::uuid;
  IF commit_row.commit_id IS NULL OR NOT coalesce(commit_row.occasion=p_occasion OR (include_unit AND commit_row.unit=p_unit),false) THEN
   RAISE insufficient_privilege USING MESSAGE='commit outside history scope'; END IF;
  IF (SELECT count(*) FROM public.client_commit_items WHERE commit_id=commit_row.commit_id)>500 THEN RAISE invalid_parameter_value USING MESSAGE='audit entry exceeds bounded authoring detail; use ordinary UI'; END IF;
  result:=public.get_client_commit_v1(commit_row.commit_id);
  IF result->>'code'<>'200' THEN RAISE insufficient_privilege USING MESSAGE='commit read denied'; END IF;
  -- Fanout metadata must not disclose identities of unrelated scopes.
  result:=jsonb_set(result,'{data,components}',coalesce((SELECT jsonb_agg(c) FROM jsonb_array_elements(result#>'{data,components}') c
   WHERE (c->>'scopeType'='occasion' AND (c->>'scopeId')::bigint=p_occasion) OR (include_unit AND c->>'scopeType'='unit' AND (c->>'scopeId')::bigint=p_unit)),'[]'::jsonb));
  RETURN result;
 ELSIF p_action='activity' THEN
  RETURN public.get_client_activity_v1(p_occasion,(p_payload->>'from')::timestamptz,(p_payload->>'to')::timestamptz);
 ELSIF p_action='orders' THEN
  IF order_id IS NULL OR NOT public.can_read_orders(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order history read denied'; END IF;
  SELECT jsonb_build_object('code',200,'data',coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id DESC),'[]'::jsonb)) INTO result FROM (
   SELECT h.id,h.created_at AS "createdAt",h.state,h.price::text AS price,h.currency_code AS currency,
    nullif(concat_ws(' ',u.name,u.surname),'') AS "actorDisplay"
   FROM eshop.orders_history h LEFT JOIN public.user_info u ON u.id=h.created_by WHERE h."order"=order_id
    AND (p_payload->>'beforeId' IS NULL OR h.id<(p_payload->>'beforeId')::bigint) ORDER BY h.id DESC LIMIT lim) page;
  RETURN result;
 ELSIF p_action='email' THEN
  IF NOT coalesce(public.email_report_allowed(p_organization,p_occasion,NULL),false) THEN RAISE insufficient_privilege USING MESSAGE='delivery history read denied'; END IF;
  result:=public.get_email_delivery_page(p_occasion,(p_payload->>'beforeId')::bigint,lim,order_id,p_payload->>'kind',p_payload->>'state',p_organization,NULL,NULL,false);
  RETURN jsonb_build_object('code',200,'data',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r->'id','kind',r->'message_kind','orderId',r->'order_id','createdAt',r->'created_at',
   'acceptedAt',r->'accepted_at','deliveredAt',r->'delivered_at','bouncedAt',r->'bounced_at','complainedAt',r->'complained_at','state',r->'state','postActionState',r->'post_action_state') ORDER BY (r->>'id')::bigint DESC)
   FROM jsonb_array_elements(result) r),'[]'::jsonb));
 ELSIF p_action='feedback' THEN
  RETURN public.get_event_feedback_export_page_internal_v1(p_occasion,(p_payload->>'after')::bigint,lim);
 END IF;
 RAISE invalid_parameter_value USING MESSAGE='unknown history projection';
END $$;
REVOKE ALL ON FUNCTION public.get_authoring_history(bigint,bigint,bigint,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_authoring_history(bigint,bigint,bigint,text,jsonb) TO authenticated,service_role;


-- Source: database/functions/authoring/exports.sql
-- Export columns are generated from the shared closed contract. No selected SQL,
-- table name, raw order snapshot, QR, hold secret or credential can be requested.
CREATE OR REPLACE FUNCTION public.authorize_authoring_export(p_occasion bigint,p_organization bigint,p_unit bigint,p_dataset text,p_columns jsonb DEFAULT '[]')
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
BEGIN
 PERFORM public.lock_people_scope_internal_v1(p_occasion,p_organization,p_unit);
 IF p_dataset IN ('report','orders') THEN
  IF NOT public.can_read_orders(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='order report/export denied'; END IF;
 ELSIF p_dataset='people' THEN
  IF NOT public.can_manage_occasion_participants(p_occasion) OR ((p_columns ?| ARRAY['email','phone','birthDate']) AND NOT public.can_read_participant_contacts(p_occasion)) THEN
   RAISE insufficient_privilege USING MESSAGE='participant export denied'; END IF;
 ELSIF p_dataset IN ('events','speakers','places') THEN PERFORM public.require_program_domain_internal_v1(p_occasion,p_dataset,false);
 ELSIF p_dataset='feedback' THEN
  IF NOT public.can_read_schedule_feedback(p_occasion) OR NOT public.get_is_event_feedback_enabled_on_occasion(p_occasion) THEN RAISE insufficient_privilege USING MESSAGE='feedback export denied'; END IF;
 ELSE RAISE invalid_parameter_value USING MESSAGE='unsupported export dataset'; END IF;
 RETURN true;
END $$;
REVOKE ALL ON FUNCTION public.authorize_authoring_export(bigint,bigint,bigint,text,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.authorize_authoring_export(bigint,bigint,bigint,text,jsonb) TO authenticated,service_role;

CREATE OR REPLACE FUNCTION public.get_authoring_export_page(p_occasion bigint,p_organization bigint,p_unit bigint,p_dataset text,p_columns jsonb,p_after text DEFAULT NULL,p_limit integer DEFAULT 50)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$
DECLARE spec jsonb:=public.authoring_export_columns_internal_v1();rows jsonb; result jsonb; next_cursor text;
BEGIN
 PERFORM public.authorize_authoring_export(p_occasion,p_organization,p_unit,p_dataset,p_columns);
 IF (spec ? p_dataset) IS NOT TRUE OR p_limit NOT BETWEEN 1 AND 50 OR jsonb_typeof(p_columns) IS DISTINCT FROM 'array' OR jsonb_array_length(p_columns) NOT BETWEEN 1 AND 20
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_columns) c WHERE NOT(spec->p_dataset->'columns' ? c))
  OR jsonb_array_length(p_columns)<>(SELECT count(DISTINCT c) FROM jsonb_array_elements_text(p_columns) c) THEN
  RAISE invalid_parameter_value USING MESSAGE='closed export columns and page required'; END IF;
 IF p_dataset='orders' THEN
  result:=public.get_operator_orders_v1(p_occasion,p_organization,p_unit,p_limit,p_after::bigint);
  next_cursor:=result->>'nextCursor';
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',r->'id','symbol',r->'symbol','state',r->'state','createdAt',r->'createdAt','ticketCount',r->'ticketCount',
   'price',r->'price','currency',r->'currency','paid',r#>'{payment,paid}') ORDER BY n),'[]'::jsonb) INTO rows FROM jsonb_array_elements(result->'orders') WITH ORDINALITY x(r,n);
 ELSIF p_dataset='people' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page."userId"),'[]'::jsonb) INTO rows FROM (
   SELECT ou."user" AS "userId",ui.name,ui.surname,ui.email_readonly AS email,ui.phone,ui.birth_date AS "birthDate",ou.role,
    coalesce((ou.data->>'is_volunteer')::boolean,false) AS "isVolunteer",coalesce(ou.is_approved,false) AS "isApproved",ou.data->>'note' AS note
   FROM public.occasion_users ou JOIN public.user_info ui ON ui.id=ou."user" WHERE ou.occasion=p_occasion AND (p_after IS NULL OR ou."user">p_after::uuid) ORDER BY ou."user" LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'userId'; END IF;
 ELSIF p_dataset='events' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.start_time AS "startTime",e.end_time AS "endTime",e.max_participants AS "maxParticipants",coalesce(v.version,0) AS "aggregateVersion"
   FROM public.events e LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='event' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='speakers' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.subtitle,e.description,coalesce(v.version,0) AS "aggregateVersion" FROM public.speakers e
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='speaker' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='places' THEN
  SELECT coalesce(jsonb_agg(to_jsonb(page) ORDER BY page.id),'[]'::jsonb) INTO rows FROM (
   SELECT e.id,e.title,e.description,e.type,coalesce(v.version,0) AS "aggregateVersion" FROM public.places e
   LEFT JOIN public.client_aggregate_versions v ON v.aggregate_type='place' AND v.scope_type='occasion' AND v.scope_id=p_occasion AND v.aggregate_id=e.id::text
   WHERE e.occasion=p_occasion AND (p_after IS NULL OR e.id>p_after::bigint) ORDER BY e.id LIMIT p_limit) page;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'id'; END IF;
 ELSIF p_dataset='feedback' THEN
  result:=public.get_event_feedback_export_page_internal_v1(p_occasion,p_after::bigint,p_limit);
  IF result->>'code'<>'200' THEN RAISE insufficient_privilege USING MESSAGE='feedback export denied'; END IF;
  -- Preserve the existing projection, but use stable feedback ID order for export pages.
  SELECT coalesce(jsonb_agg(r ORDER BY (r->>'feedback_id')::bigint),'[]'::jsonb) INTO rows FROM jsonb_array_elements(result->'data') r;
  IF jsonb_array_length(rows)=p_limit THEN next_cursor:=rows->-1->>'feedback_id'; END IF;
 END IF;
 -- Drop unselected columns in SQL before any personal data crosses the boundary.
 SELECT coalesce(jsonb_agg((SELECT jsonb_object_agg(k,v) FROM jsonb_each(r) x(k,v) WHERE p_columns ? k) ORDER BY n),'[]'::jsonb) INTO rows
 FROM jsonb_array_elements(coalesce(rows,'[]')) WITH ORDINALITY x(r,n);
 RETURN jsonb_build_object('columns',p_columns,'rows',rows,'nextCursor',next_cursor);
END $$;
REVOKE ALL ON FUNCTION public.get_authoring_export_page(bigint,bigint,bigint,text,jsonb,text,integer) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.get_authoring_export_page(bigint,bigint,bigint,text,jsonb,text,integer) TO authenticated,service_role;
